 string LowerItemEffect(ItemStack s)
 {
  if(!LowerMallEnabled)return "";if(s.ItemId.StartsWith("item.exterior."))return s.Definition.Equipment?.Family is {} ext&&(ext.StartsWith("ext30-")||ext.StartsWith("ext31-"))?ext:"";if(s.ItemId.StartsWith("item.roof."))return s.Definition.Equipment?.Family is {} rf&&rf.StartsWith("roof-")&&rf!="roof-flare"?rf:"";if(s.ItemId.StartsWith("item.upper."))return s.Definition.Equipment?.Family is {} family&&(family.StartsWith("upper-")||family.StartsWith("upper26-")||family.StartsWith("upper27-"))?family:"";if(!s.ItemId.StartsWith("item.lower."))return "";string final=Lower24ItemEffect(s);if(final!="")return final;string chapter=Lower23ItemEffect(s);if(chapter!="")return chapter;string n=s.Definition.Name.ToLowerInvariant();foreach(var pair in new[]{("caffeine","caffeine"),("eye drops","eyedrops"),("herbal medicine","herbal"),("skincare","skincare"),("painkiller","painkiller"),("self-tanning","spray"),("luxury perfume","perfume"),("emp device","emp"),("expired flour","flour"),("fertilizer","fire"),("energy drink","energy"),("anti-reflective","glasses"),("survival book","study"),("night vision","nightvision"),("tactical goggles","nightvision"),("walkman","audio"),("speaker","audio"),("radio","audio"),("first aid","firstaid"),("medical kit","firstaid"),("caviar","riskyfood"),("aged meat","riskyfood"),("frozen meat","riskyfood"),("canned","food"),("peaches","food"),("chocolate","food"),("snacks","food"),("bottled water","water")})if(n.Contains(pair.Item1))return pair.Item2;return "";
 }
 public string LowerItemUseReason(Actor a,ItemStack s)=>Roof28ItemReason(a,s) is {} roof&&roof!=""?roof:Upper27ItemReason(a,s) is {} upper27&&upper27!=""?upper27:Upper26ItemReason(a,s) is {} upper26&&upper26!=""?upper26:Upper25ItemReason(a,s) is {} upper&&upper!=""?upper:Lower24ItemReason(a,s) is {} final&&final!=""?final:a.Character.HasCondition("chapter-emp")&&LowerItemEffect(s) is "audio" or "nightvision" or "chapter-smart"?"Powered gear is disabled by the EMP.":LowerItemEffect(s)==""?"No defined direct use.":!a.Alive||!Party.Contains(a)||ReactionInterruptActive||Mode is Mode.Defeat or Mode.Victory||Mode==Mode.Combat&&!CanAct(a)?"Choose the active conscious survivor with an available Action.":s.Definition.MaxCharges>0&&s.Charges<=0?"No charges remain.":"";
 public bool UseLowerMallItem(Actor a,string id)
 {
  var s=a.Inventory.FindInstance(id);if(s==null||LowerItemUseReason(a,s)!="")return false;string effect=LowerItemEffect(s);if(Mode==Mode.Combat&&!SpendAction(a,"Use recovered gear"))return false;
  bool consume=effect is not ("audio" or "study" or "glasses" or "nightvision" or "chapter-smart" or "final-defib" or "final-lucky" or "upper-audio" or "upper-laserpointer" or "upper26-cloak" or "upper27-audio" or "upper27-noise" or "upper27-diversion" or "roof-radio" or "ext30-radio" or "ext30-flashlight");switch(effect)
  {
   default:if(effect.StartsWith("ext31-"))UseExterior31Item(a,s,effect);else if(effect.StartsWith("ext30-"))UseExterior30Item(a,s,effect);else if(effect.StartsWith("roof-"))UseRoof28Item(a,s,effect);else if(effect.StartsWith("upper27-"))UseUpper27Item(a,s,effect);else if(effect.StartsWith("upper26-"))UseUpper26Item(a,s,effect);else if(effect.StartsWith("upper-"))UseUpper25Item(a,s,effect);else if(effect.StartsWith("final-"))UseLower24Item(a,s,effect);else UseLower23Item(a,s,effect);break;
   case "caffeine":LowerEffect(a,"book-caffeine",3600);break;case "eyedrops":a.Hp=Math.Min(a.MaxHp,a.Hp+1);LowerEffect(a,"book-eyedrops",3600);break;case "painkiller":a.Hp=Math.Min(a.MaxHp,a.Hp+Roll(6));break;
   case "firstaid":a.Hp=Math.Min(a.MaxHp,a.Hp+5);a.Character.SetCondition("book-infected","Infection",false);break;
   case "herbal":foreach(var c in new[]{"poisoned","book-infected","book-disoriented"})a.Character.SetCondition(c,c,false);LowerMallEffects.RemoveAll(e=>e.ActorId==a.Id&&e.Condition is "poisoned" or "book-infected" or "book-disoriented");break;
   case "skincare":a.Character.HitPoints.Temporary=Math.Max(1,a.Character.HitPoints.Temporary);break;case "spray":LowerEffect(a,"book-stealth",Roll(6)*3600);break;case "energy":LowerEffect(a,"book-stealth",6);break;case "glasses":LowerEffect(a,"book-glasses",86400);break;case "nightvision":LowerEffect(a,"book-darkvision",86400);break;case "study":a.Character.SetCondition("book-studied","Studied Backyard Apocalypse",true);break;
   case "food":a.Needs.LastFoodMinute=CampaignMinutes;a.Needs.FoodTaken=true;break;case "water":a.Needs.LastWaterMinute=CampaignMinutes;a.Needs.WaterTaken=true;break;case "riskyfood":if(Roll(2)==1||!SurvivorSave(a,Ability.Constitution,14,"spoiled food"))LowerEffect(a,"poisoned",Roll(6)*3600);else{a.Needs.LastFoodMinute=CampaignMinutes;a.Needs.FoodTaken=true;}break;
   case "audio":EmitLocalNoise(a,"door",100);ChangeTension(2,"Portable audio distraction");break;
   case "emp":case "perfume":case "flour":case "fire":foreach(var target in Actors.Where(e=>e.Enemy&&e.Alive&&e.Position.Distance(a.Position)<=(effect=="emp"?6:2)&&Line(a.Position,e.Position)).ToArray()){if(effect=="emp"&&LowerTraits(target).Contains("cyber")||effect=="perfume"&&target.Name=="The Last Employee")LowerEffect(target,"stunned",6);else if(effect=="flour"&&!SurvivorSave(target,Ability.Constitution,12,"flour"))LowerEffect(target,"blinded",6);else if(effect=="fire")Hurt(target,RollDamage(2,6),DamageType.Fire,a);}if(effect is "emp" or "fire")EmitLocalNoise(a,"explosion",150);break;
  }
  if(consume){if(s.Definition.MaxCharges>0){if(--s.Charges==0){s.ConsumeResourceUnits(1);a.Inventory.Items.Remove(s);}}else{s.ConsumeResourceUnits(1);if(--s.Quantity==0)a.Inventory.Items.Remove(s);}}a.QuickAccess.Normalize(a);a.Statistics.ItemsUsed++;if(Mode==Mode.Combat)CheckEnd();return true;
 }
